-- ناروَن: schema اولیه. این فایل را در Supabase SQL Editor اجرا کنید.
create extension if not exists pgcrypto;
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.products(id bigint generated by default as identity primary key, slug text unique, name text not null, description text not null default '', price_toman bigint not null check(price_toman>=0), stock integer not null default 0 check(stock>=0), image_url text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(), order_code text not null unique, customer_name text not null, customer_phone text not null, province text not null, city text not null, postal_code text not null, address text not null, items jsonb not null, subtotal bigint not null check(subtotal>=0), shipping_amount bigint not null default 0 check(shipping_amount>=0), total_amount bigint not null check(total_amount>=0), payment_method text not null default 'bank_transfer' check(payment_method in ('bank_transfer','cod')), status text not null default 'pending' check(status in ('pending','payment_submitted','paid','processing','shipped','completed','cancelled')), transfer_reference text, admin_note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.site_settings(key text primary key, value text not null default '', updated_at timestamptz not null default now());
create index if not exists orders_created_at_idx on public.orders(created_at desc); create index if not exists orders_status_idx on public.orders(status); create index if not exists products_active_idx on public.products(active);
alter table public.admin_users enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.site_settings enable row level security;
create or replace function public.is_narvan_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()); $$;
revoke all on function public.is_narvan_admin() from public; grant execute on function public.is_narvan_admin() to authenticated;
drop policy if exists "admins read admin list" on public.admin_users; create policy "admins read admin list" on public.admin_users for select to authenticated using (public.is_narvan_admin());
drop policy if exists "public read active products" on public.products; create policy "public read active products" on public.products for select to anon,authenticated using (active or public.is_narvan_admin());
drop policy if exists "admins manage products" on public.products; create policy "admins manage products" on public.products for all to authenticated using (public.is_narvan_admin()) with check (public.is_narvan_admin());
drop policy if exists "admins read orders" on public.orders; create policy "admins read orders" on public.orders for select to authenticated using (public.is_narvan_admin());
drop policy if exists "admins update orders" on public.orders; create policy "admins update orders" on public.orders for update to authenticated using (public.is_narvan_admin()) with check (public.is_narvan_admin());
drop policy if exists "public read safe payment settings" on public.site_settings; create policy "public read safe payment settings" on public.site_settings for select to anon,authenticated using (key in ('payment_iban','payment_holder','payment_note') or public.is_narvan_admin());
drop policy if exists "admins manage settings" on public.site_settings; create policy "admins manage settings" on public.site_settings for all to authenticated using (public.is_narvan_admin()) with check (public.is_narvan_admin());
-- سفارش عمومی فقط از Edge Function با service-role نوشته می‌شود؛ هیچ policy برای insert عمومی نگذارید.
insert into public.site_settings(key,value) values ('payment_iban','IR980180000000377811342397'),('payment_holder',''),('payment_note','پس از انتقال وجه، شماره پیگیری را اعلام کنید. سفارش تا تأیید مدیر در انتظار می‌ماند.') on conflict(key) do nothing;
